public void initFromFreeItemLine(
    Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine _crtFreeItemLine,
    GUPFreeItemLine _gupFreeItemLine)
{
    this.IsFreeItemLine = NoYes::Yes;
    this.SkipPriceDiscCalc = NoYes::Yes;
    this.GUPFreeItemLineRecId = _gupFreeItemLine.RecId;
    this.ItemId = _crtFreeItemLine.ItemId;
    this.initFromInventTable(InventTable::find(this.ItemId), false);

    if (_gupFreeItemLine.Variant)
    {
        this.RetailVariantId = InventDimCombination::findByDistinctProductVariant(_gupFreeItemLine.Variant).RetailVariantId;
        InventDim variantInventDim = InventDimCombination::findVariantId(this.RetailVariantId).inventDim();
        this.updateProductDimensions(variantInventDim);
    }

    InventDim inventDimSalesLine = InventDim::find(this.InventDimId);
    InventDim inventDimFreeItemLine = InventDim::find(_gupFreeItemLine.InventDimId);
    if (inventDimFreeItemLine.InventSiteId)
    {
        inventDimSalesLine.InventSiteId = inventDimFreeItemLine.InventSiteId;
        inventDimSalesLine.InventLocationId = '';
    }
    if (inventDimFreeItemLine.InventLocationId)
    {
        inventDimSalesLine.InventLocationId = inventDimFreeItemLine.InventLocationId;
    }
    this.InventDimId = InventDim::findOrCreate(inventDimSalesLine).inventDimId;

    this.updateFromCRTFreeItemLine(_crtFreeItemLine);
}

public boolean updateFromCRTFreeItemLine(Microsoft.Dynamics.Commerce.Runtime.DataModel.AttributeBasedPricing.FreeItemLine _crtFreeItemLine)
{
    this.SalesQty = _crtFreeItemLine.Quantity * _crtFreeItemLine.QuantityFactor;
    this.SalesUnit = _crtFreeItemLine.UnitOfMeasureSymbol;
    this.SalesPrice = _crtFreeItemLine.Price;
    this.PriceUnit = _crtFreeItemLine.PriceUnit;
    this.lineDisc = this.SalesPrice;
    if (this.SalesQty != this.orig().SalesQty
        || this.SalesUnit != this.orig().SalesUnit
        || this.SalesPrice != this.orig().SalesPrice
        || this.PriceUnit != this.orig().PriceUnit
        || this.lineDisc != this.orig().lineDisc)
    {
        SalesLine::modifySalesQty(this, this.inventDim(), false, false);
        InventMovement::bufferSetTransQtyUnit(this);
        this.setInventDeliverNow();
        InventMovement::bufferSetRemainQty(this);
        return true;
    }

    return false;
}

public boolean modifyInventDim(
    InventDim            _inventDim,
    FieldId              _dimFieldId,
    boolean              _resetPrice)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && this.IsFreeItemLine)
    {
        _resetPrice = false;
    }

    return next modifyInventDim(_inventDim, _dimFieldId, _resetPrice);
}

public void createOrUpdateRetailSalesDiscountLine(GUPFreeItemLine _gupFreeItemLine)
{
    RetailSalesDiscountLine retailSalesDiscountLine;

    select firstonly retailSalesDiscountLine where retailSalesDiscountLine.InventTransId == this.InventTransId;

    ttsbegin;
    if (retailSalesDiscountLine.RecId)
    {
        retailSalesDiscountLine.selectForUpdate(true);
        retailSalesDiscountLine.Amount = this.lineDisc * this.SalesQty;
        if (this.PriceUnit)
        {
            retailSalesDiscountLine.Amount = retailSalesDiscountLine.Amount / this.PriceUnit;
        }

        if (retailSalesDiscountLine.orig().Amount != retailSalesDiscountLine.Amount)
        {
            retailSalesDiscountLine.update();
        }
    }
    else
    {
        retailSalesDiscountLine.clear();
        retailSalesDiscountLine.InventTransId = this.InventTransId;
        retailSalesDiscountLine.Amount = this.lineDisc * this.SalesQty;
        if (this.PriceUnit)
        {
            retailSalesDiscountLine.Amount = retailSalesDiscountLine.Amount / this.PriceUnit;
        }
        retailSalesDiscountLine.CustomerDiscountType = RetailCustomerDiscountType::None;
        retailSalesDiscountLine.Percentage = 100;
        retailSalesDiscountLine.DiscountOriginType = RetailDiscountOriginType::Periodic;
        retailSalesDiscountLine.ManualDiscountType = RetailManualDiscountType::None;
        retailSalesDiscountLine.PeriodicDiscountOfferId = _gupFreeItemLine.FreeItemId;
        retailSalesDiscountLine.insert();
    }
    ttscommit;
}

public static void modifySalesQty(SalesLine    _salesLine,
                           InventDim    _inventDim,
                           boolean      _resetPrice,
                           boolean      _uiEnabled)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && _salesLine.IsFreeItemLine)
    {
        _resetPrice = false;
    }

    next modifySalesQty(_salesLine, _inventDim, _resetPrice, _uiEnabled);
}

private void updateProductDimensions(InventDim _variantInventDim)
{
    InventDim inventDimSalesLine = InventDim::find(this.InventDimId);
    Set productDimensionFields = inventDimSalesLine.copyProductDimensionsAndGetModifiedDimensionFields(_variantInventDim, this.ItemId);

    if (productDimensionFields)
    {
        this.modifyInventDimSet(inventDimSalesLine, productDimensionFields, false);
    }
}

protected boolean shouldUpdateRetailDiscountsInternal(RetailSalesTable _retailSales)
{
    boolean ret = next shouldUpdateRetailDiscountsInternal(_retailSales);

    ret = ret || GUPParameters::asRetailSalesOrder();

    return ret;
}

protected void updateRetailSalesPriceAdjustmentLine(RetailSalesOrderCalculatorResult _result, SalesLine _locSalesLine)
{
    next updateRetailSalesPriceAdjustmentLine(_result, _locSalesLine);

    if (GUPParameters::asRetailSalesOrder())
    {
        GUPSalesBasePriceLineMap basePriceLineMap;

        if (!_result.getBasePriceLineList().empty())
        {
            ListEnumerator basePriceLineEn = _result.getBasePriceLineList().getEnumerator();
            while (basePriceLineEn.moveNext())
            {
                basePriceLineMap = basePriceLineEn.current();
                GUPPriceDetailsHelper::findOrCreateMCRPriceHistory(basePriceLineMap, _locSalesLine);
            }
        }
        else
        {
            GUPPriceDetailsHelper::clearPriceHistory(_locSalesLine);
        }

        GUPMarginComponentAdjustmentHistory::deleteHistory(_locSalesLine.InventTransId);

        RetailSalesPriceAdjustmentLine adjustmentLine;

        ListEnumerator adjustmentLineEn = _result.getRetailSalesPriceAdjustmentLineList().getEnumerator();
        while (adjustmentLineEn.moveNext())
        {
            adjustmentLine = adjustmentLineEn.current();

            GUPPriceDetailsHelper::updateGUPMarginComponentAdjustmentHistory(
                adjustmentLine.RetailPeriodicDiscountLineRefRecId,
                adjustmentLine.Amount,
                adjustmentLine.DiscountMethod,
                _locSalesLine);
        }
    }
}
